window.HOEREN_TESTS[71] = {"id":"muelltrennung-und-recycling","name":"Mülltrennung und Recycling","teile":[{"type":"mc","title":"Teil 1: Fünf kurze Texte","instruction":"Sie hören fünf kurze Texte. Sie hören jeden Text zweimal. Wählen Sie a, b oder c.","items":[{"transcript":"Liebe Bewohner: Die Müllabfuhr ändert die Zeiten. Die graue Tonne wird ab Mai nicht mehr am Montag geleert und nicht am Freitag, sondern am Mittwoch. Die gelbe Tonne bleibt am Freitag. Bitte stellen Sie die Tonnen am Abend vorher raus. Den genauen Plan finden Sie im Briefkasten. Vielen Dank!","gender":"f","q":"Wann wird die graue Tonne jetzt geleert?","opts":["Am Mittwoch.","Am Montag.","Am Freitag."],"correct":0},{"transcript":"Hallo Tom, hier ist Markus. Pass auf, ich verstehe das mit der Mülltrennung nicht. Wohin kommt eigentlich die Pizza-Schachtel aus Pappe? Nicht wann der Müll abgeholt wird und nicht wo die Tonne steht. In das Papier oder in den Restmüll, wenn sie schmutzig ist? Ruf mich an, ich will es richtig machen. Danke dir!","gender":"m","q":"Worüber ist Markus unsicher?","opts":["Wann der Müll abgeholt wird.","Wohin die Pizza-Schachtel kommt.","Wo die Tonne steht."],"correct":1},{"transcript":"Achtung Bürger: Der Wertstoffhof ist umgezogen. Sie finden ihn jetzt nicht mehr in der Industriestraße und nicht im Zentrum, sondern am Stadtrand, neben dem Sportplatz. Alte Möbel, Elektrogeräte und Farben können Sie dort kostenlos abgeben. Geöffnet ist samstags von 8 bis 14 Uhr. Bitte beachten Sie die neue Adresse!","gender":"m","q":"Wo ist der Wertstoffhof jetzt?","opts":["In der Industriestraße.","Am Stadtrand beim Sportplatz.","Im Zentrum."],"correct":1},{"transcript":"Hi Lisa, hier ist Anna. Ich sammle jetzt Pfandflaschen und bringe sie zum Supermarkt, ich werfe sie nicht weg und stelle sie nicht in die gelbe Tonne. Pro Flasche 25 Cent, das lohnt sich! Ich habe schon zehn Euro gespart. Bringst du deine auch mit? Wir gehen zusammen. Sag Bescheid!","gender":"f","q":"Was macht Anna mit den Pfandflaschen?","opts":["Sie wirft sie weg.","Sie stellt sie in die gelbe Tonne.","Sie bringt sie zum Supermarkt."],"correct":2},{"transcript":"Liebe Bewohner: Ab Juni gibt es eine neue braune Tonne für Bioabfall. Dort kommen Essensreste, Obstschalen und Gartenabfälle hinein. Plastik gehört auf keinen Fall hinein, und Glas auch nicht. Aus dem Bioabfall wird Kompost und Energie gewonnen. Die Tonne ist kostenlos. Melden Sie sich bei der Stadt an!","gender":"f","q":"Was kommt in die braune Tonne?","opts":["Bioabfall.","Plastik.","Glas."],"correct":0}]},{"type":"match","title":"Teil 2: Ein Gespräch","instruction":"Sie hören ein Gespräch. Sie hören den Text einmal. Wer macht was? Wählen Sie für jede Person einen Buchstaben (a–i).","lines":[{"speaker":"Lukas","gender":"m","text":"Hallo Lisa! In der Küche stehen die Tonnen durcheinander und ich will Ordnung schaffen."},{"speaker":"Lisa","gender":"f","text":"Schön, dass du das ansprichst. Jeder bei uns kann eine klare Aufgabe übernehmen."},{"speaker":"Lukas","gender":"m","text":"Ich trenne den Müll genau. Jede Tonne bekommt bei mir einen festen Deckel."},{"speaker":"Lisa","gender":"f","text":"Ich sammle Pfandflaschen. Im Keller stehen schon zwei volle Taschen für den Laden."},{"speaker":"Lukas","gender":"m","text":"Spart jemand bei uns im Alltag extra Strom?"},{"speaker":"Lisa","gender":"f","text":"Nein. Strom spart bei uns gerade niemand."},{"speaker":"Lukas","gender":"m","text":"Tom hat hinter dem Haus einen kleinen Garten mit Beeten."},{"speaker":"Lisa","gender":"f","text":"Tom kompostiert Bioabfälle. Aus Schalen wird mit der Zeit gute Erde."},{"speaker":"Lukas","gender":"m","text":"Sara geht samstags mit eigenen Dosen auf den Markt."},{"speaker":"Lisa","gender":"f","text":"Sara kauft ohne Verpackung ein. Obst und Reis kommen lose in ihre Dosen."},{"speaker":"Lukas","gender":"m","text":"Spart jemand bei uns Wasser beim langen Duschen?"},{"speaker":"Lisa","gender":"f","text":"Nein. Wasser sparen wir nicht. Darüber haben wir noch keinen Plan."},{"speaker":"Lukas","gender":"m","text":"Tim hat einen alten Fernseher und ein kaputtes Radio im Keller liegen."},{"speaker":"Lisa","gender":"f","text":"Tim bringt alte Geräte zum Wertstoffhof. Am Samstag fährt er mit dem Auto hin."},{"speaker":"Lukas","gender":"m","text":"Dann schreibe ich die Aufgaben klar auf einen Zettel."},{"speaker":"Lisa","gender":"f","text":"Ich hänge ihn direkt an die gelbe Tonne in der Küche."}],"options":[{"letter":"a","text":"Spart Strom"},{"letter":"b","text":"Trennt den Müll genau"},{"letter":"c","text":"Bringt alte Geräte zum Wertstoffhof"},{"letter":"d","text":"Fährt nur Fahrrad"},{"letter":"e","text":"Sammelt Pfandflaschen"},{"letter":"f","text":"Spart Wasser"},{"letter":"g","text":"Kauft ohne Verpackung ein"},{"letter":"h","text":"Kompostiert Bioabfälle"},{"letter":"i","text":"Kauft Second-Hand-Kleidung"}],"items":[{"person":"Lukas","correct":"b"},{"person":"Lisa","correct":"e"},{"person":"Tom","correct":"h"},{"person":"Sara","correct":"g"},{"person":"Tim","correct":"c"}]},{"type":"mc","title":"Teil 3: Fünf kurze Gespräche","instruction":"Sie hören fünf kurze Gespräche. Sie hören jedes Gespräch einmal. Wählen Sie a, b oder c.","items":[{"lines":[{"speaker":"Nachbarin","gender":"f","text":"Guten Tag, wohin kommt das Altglas? Alles zusammen in die graue Tonne?"},{"speaker":"Nachbar","gender":"m","text":"Nicht alles zusammen und nicht in die graue Tonne. In den Container an der Ecke."},{"speaker":"Nachbarin","gender":"f","text":"Auch nach Farben getrennt, weiß, grün und braun?"},{"speaker":"Nachbar","gender":"m","text":"Ja, nach Farben getrennt, weißes, grünes und braunes extra. Bitte nicht mischen."},{"speaker":"Nachbarin","gender":"f","text":"Danke, dann werfe ich das Glas nach Farben getrennt in den Container."}],"q":"Wie soll man das Altglas einwerfen?","opts":["Alles zusammen.","Nach Farben getrennt.","In die graue Tonne."],"correct":1},{"lines":[{"speaker":"Mann","gender":"m","text":"Guten Tag, wohin mit dem alten Kühlschrank? Kostet das Abholen 20 Euro oder 10 Euro?"},{"speaker":"Mitarbeiterin","gender":"f","text":"Zum Wertstoffhof oder wir holen ihn ab."},{"speaker":"Mann","gender":"m","text":"Was kostet das Abholen, 20 Euro?"},{"speaker":"Mitarbeiterin","gender":"f","text":"Für große Geräte ist es kostenlos, nicht 20 Euro und nicht 10 Euro."},{"speaker":"Mann","gender":"m","text":"Super, dann ist das Abholen kostenlos. Wann können Sie kommen?"}],"q":"Was kostet das Abholen des Kühlschranks?","opts":["Es ist kostenlos.","20 Euro.","10 Euro."],"correct":0},{"lines":[{"speaker":"Tochter","gender":"f","text":"Papa, wohin kommt die Plastikflasche? Zurück in den Laden oder in den Restmüll?"},{"speaker":"Vater","gender":"m","text":"Wenn Pfand drauf ist, zurück in den Laden. Schau mal auf das Logo."},{"speaker":"Tochter","gender":"f","text":"Und ohne Pfand, Restmüll?"},{"speaker":"Vater","gender":"m","text":"Nein, ohne Pfand in die gelbe Tonne, nicht in den Restmüll."},{"speaker":"Tochter","gender":"f","text":"Okay, ohne Pfand gelbe Tonne, mit Pfand zurück in den Laden. Danke."}],"q":"Wohin kommt eine Plastikflasche ohne Pfand?","opts":["Zurück in den Laden.","In den Restmüll.","In die gelbe Tonne."],"correct":2},{"lines":[{"speaker":"Frau","gender":"f","text":"Guten Tag, wann ist die Sperrmüll-Abholung? Muss ich den Müll selbst bringen oder nichts tun?"},{"speaker":"Mitarbeiter","gender":"m","text":"Nächsten Dienstag holen wir ab, Sie müssen den Müll nicht selbst bringen."},{"speaker":"Frau","gender":"f","text":"Muss ich mich anmelden, oder reicht nichts tun?"},{"speaker":"Mitarbeiter","gender":"m","text":"Ja, Sie müssen sich vorher anmelden, bitte anrufen. Nichts tun reicht nicht."},{"speaker":"Frau","gender":"f","text":"Gut, ich rufe an und melde mich an. Danke für den Tipp."}],"q":"Was muss die Frau tun?","opts":["Den Müll selbst bringen.","Nichts.","Sich vorher anmelden."],"correct":2},{"lines":[{"speaker":"Kunde","gender":"m","text":"Guten Tag, wo ist der Pfandautomat? Bekomme ich Bargeld oder nichts?"},{"speaker":"Verkäuferin","gender":"f","text":"Hinten links beim Eingang. Bargeld bekommen Sie dort nicht, und mit leeren Händen gehen Sie auch nicht."},{"speaker":"Kunde","gender":"m","text":"Bekomme ich Geld oder einen Bon?"},{"speaker":"Verkäuferin","gender":"f","text":"Einen Bon, den lösen Sie an der Kasse ein. Kein Bargeld am Automaten."},{"speaker":"Kunde","gender":"m","text":"Verstehe, einen Bon, dann zur Kasse. Danke schön."}],"q":"Was bekommt der Kunde am Pfandautomaten?","opts":["Einen Bon.","Bargeld.","Nichts."],"correct":0}]},{"type":"jn","title":"Teil 4: Interview","instruction":"Sie hören ein Interview mit Frau Neumann, einer Umweltberaterin der Stadt. Sie hören das Interview zweimal. Ja oder Nein?","transcript":[{"speaker":"Reporter","gender":"m","text":"Frau Neumann, warum ist Mülltrennung so wichtig?"},{"speaker":"Neumann","gender":"f","text":"Weil wir damit Rohstoffe sparen. Aus altem Papier wird neues Papier, aus Glas neues Glas. Wenn wir alles in eine Tonne werfen, geht das verloren. Mülltrennung ist eigentlich Recycling — und das schützt unsere Natur und spart Energie. Jeder kann mitmachen."},{"speaker":"Reporter","gender":"m","text":"Machen die Menschen das richtig?"},{"speaker":"Neumann","gender":"f","text":"Die meisten geben sich Mühe, aber es gibt viele Fehler. Plastik in der Biotonne ist ein großes Problem. Oder Batterien im normalen Müll — die sind sogar gefährlich. Da müssen wir noch viel aufklären. Aber im Vergleich zu früher ist es schon viel besser geworden."},{"speaker":"Reporter","gender":"m","text":"Was ist der wichtigste Tipp?"},{"speaker":"Neumann","gender":"f","text":"Müll vermeiden ist besser als Müll trennen. Kaufen Sie weniger Verpackung, nehmen Sie eigene Taschen mit, reparieren Sie Sachen statt sie wegzuwerfen. Der beste Müll ist der, der gar nicht erst entsteht. Das vergessen viele über dem ganzen Trennen."},{"speaker":"Reporter","gender":"m","text":"Wie ist es mit Elektrogeräten?"},{"speaker":"Neumann","gender":"f","text":"Die gehören niemals in den Hausmüll. Sie enthalten Schadstoffe, aber auch wertvolle Metalle. Bringen Sie alte Handys und Geräte zum Wertstoffhof oder zurück in den Laden. Viele wissen das nicht und werfen sie einfach weg. Das ist wirklich schade um die Rohstoffe."},{"speaker":"Reporter","gender":"m","text":"Wie sehen Sie die Zukunft?"},{"speaker":"Neumann","gender":"f","text":"Ich bin optimistisch. Die jungen Leute denken viel mehr an die Umwelt als früher. Es gibt immer mehr verpackungsfreie Läden und Reparatur-Cafés. Wenn wir alle ein bisschen mitmachen, schaffen wir viel. Jeder Einzelne zählt — das ist meine feste Überzeugung."}],"items":[{"q":"Durch Mülltrennung kann man Rohstoffe sparen.","correct":"ja"},{"q":"Batterien gehören in den normalen Hausmüll.","correct":"nein"},{"q":"Frau Neumann findet, Müll vermeiden ist besser als trennen.","correct":"ja"},{"q":"Alte Elektrogeräte darf man in den Hausmüll werfen.","correct":"nein"},{"q":"Sie ist optimistisch für die Zukunft.","correct":"ja"}]}]};
